long media_enum_entities(struct media_device *mdev, struct media_entity_desc __user *uent)
{
    struct media_entity_desc kent = {0};
    struct media_entity *entity;
    int ret = 0;

    if (!mdev || !uent) {
        return -EINVAL;
    }

    if (copy_from_user(&kent, uent, sizeof(kent))) {
        return -EFAULT;
    }

    if (kent.index >= mdev->entity_count) {
        return -EINVAL;
    }

    entity = media_device_get_entity(mdev, kent.index);
    if (!entity) {
        return -EINVAL;
    }

    kent.id = entity->id;
    kent.name = entity->name;
    kent.type = entity->type;
    kent.flags = entity->flags;
    kent.group_id = entity->group_id;
    kent.pad_num = entity->num_pads;
    kent.link_num = entity->num_links;

    if (copy_to_user(uent, &kent, sizeof(kent))) {
        return -EFAULT;
    }

    return ret;
}
